// Official Macedonian Mathematics Curriculum — БРО (Биро за развој на образованието)
// Source: bro.gov.mk/nastavni-programi/  |  Last sync: 2026-05

export interface LearningOutcome {
  code: string;        // e.g. "МА.6.1.2"
  text: string;        // What the student should be able to do
}

export interface CurriculumTopic {
  id: string;
  name: string;
  name_short: string;
  hours: number;        // Approximate teaching hours for this topic
  outcomes: LearningOutcome[];
  /**
   * What the teacher assesses against for this topic, as the programme words it.
   * Present on the imported secondary programmes.
   */
  assessment_standards?: string[];
  /** Concepts from earlier grades this topic builds on, by their source ids. */
  prerequisite_concept_ids?: string[];
  /**
   * Cross-subject national standards (`III-A.*`) this topic contributes to.
   *
   * Kept apart from `outcomes`: the shared curriculum contract §7 excludes them
   * from outcomes, and mixing them in meant a national standard could be
   * reported as a subject outcome in the mastery rollup.
   */
  national_standards?: LearningOutcome[];
  keywords: string[];   // For keyword-based RAG fallback
  example_tasks: string[]; // Typical task phrasings in Macedonian
}

/** The БРО decision that enacted a programme. */
export interface CurriculumDocument {
  /** Document number, e.g. `13-13739/9`. */
  number: string;
  /** ISO date the minister signed it. */
  date: string;
  /** School year it takes effect, e.g. `2026/2027`. */
  inForceFrom: string;
}

export interface CurriculumGrade {
  grade: string;          // "1", "2", ... "9", "1год", "2год", "3год", "4год"
  level_label: string;    // "VI одделение", "I година гимназија"
  education_track: EducationTrack;
  hours_per_week: number;
  topics: CurriculumTopic[];
  /** The document this programme was transcribed from, where it is known. */
  document?: CurriculumDocument;
  /**
   * Grade key of the programme that replaced this one.
   *
   * A superseded programme is kept, never deleted. Its outcome codes carry its
   * own grade token, so a task a teacher tagged against it still resolves —
   * deleting it would strand every one of those refs. What changes is only that
   * new work is classified against the replacement.
   */
  superseded_by?: string;
}

export type EducationTrack =
  | 'primary'                 // Основно образование (1–9)
  | 'secondary_general'       // Општа гимназија (4 години)
  | 'secondary_math_info'     // Математичко-информатичка гимназија
  | 'gymnasium_elective'      // Гимназиски изборни програми
  /**
   * Vocational is three distinct БРО programmes, not one. They differ in
   * duration, weekly hours and themes; treating them as a single track meant a
   * teacher in a two- or three-year profile saw another programme's outcomes.
   * `secondary_vocational` is kept as the four-year track's historical key so
   * existing tasks and saved references keep resolving.
   */
  | 'secondary_vocational'    // Стручно 4-годишно (историски клуч)
  | 'secondary_vocational_2'  // Стручно 2-годишно
  | 'secondary_vocational_3'  // Стручно 3-годишно
  | 'secondary_vocational_4'; // Стручно 4-годишно (експлицитно)

